export function departementParCode(code) {
  return DEPARTEMENTS_FRANCE.find((d) => d.code === code) || null;
}

export function departementPourVille(ville) {
  const normalized = String(ville || '').trim().toLocaleLowerCase('fr-FR');
  const match = VILLES_PRINCIPALES.find((v) => v.nom.toLocaleLowerCase('fr-FR') === normalized);
  return match ? departementParCode(match.departementCode) : null;
}

