export function codePourDepartement(nom) {
  const normalized = String(nom || '').trim().toLocaleLowerCase('fr-FR');
  return DEPARTEMENTS_FRANCE.find((d) => d.nom.toLocaleLowerCase('fr-FR') === normalized)?.code || '';
}
